(()=>{'use strict';const $=s=>document.querySelector(s);let items=[],user,filter='open',kind='task',loading=false,mutating=false,requestId=crypto.randomUUID();
const el=(tag,text)=>{const n=document.createElement(tag);n.textContent=text;return n;};
async function api(path='',body){const r=await fetch('/api/admin/tasks'+path,{cache:'no-store',...(body?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}:{})});const d=await r.json();if(!r.ok)throw Error(d.error||'Не удалось загрузить дела.');return d;}
function notice(s){$('#tasks-notice').textContent=s;}
function render(){const selected=items.filter(t=>t.kind===kind),open=selected.filter(t=>!t.completed_at).length;$('#task-day-note').textContent=kind==='task'?'Разовые дела остаются до выполнения.':'Чек-лист на '+new Date().toLocaleDateString('ru-RU',{timeZone:'Europe/Moscow'})+' · отметки сохраняются отдельно за каждый день';document.querySelectorAll('[data-kind]').forEach(b=>{const group=items.filter(t=>t.kind===b.dataset.kind),done=group.filter(t=>t.completed_at).length;const names={task:'Разовые дела',opening:'Открытие',during:'Во время смены',closing:'Закрытие'};b.textContent=names[b.dataset.kind]+' · '+done+'/'+group.length;});$('#task-count').textContent=`Нужно сделать: ${open} · Выполнено: ${selected.length-open}`;const root=$('#task-list');root.replaceChildren();const shown=selected.filter(t=>filter==='all'||(filter==='done')===Boolean(t.completed_at));for(const task of shown){const row=el('article','');row.className='task-row'+(task.completed_at?' done':'');const label=el('label',''),check=document.createElement('input');check.type='checkbox';check.checked=Boolean(task.completed_at);check.disabled=mutating;check.setAttribute('aria-label',(task.completed_at?'Вернуть в работу: ':'Выполнить: ')+task.text);const copy=el('span','');copy.append(el('strong',task.text));const at=task.completed_at||task.created_at;copy.append(el('small',`${task.completed_at?'Выполнил: '+task.completed_name:'Добавил: '+task.created_name} · ${new Date(at).toLocaleString('ru-RU',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'})}`));label.append(check,copy);row.append(label);root.append(row);check.onchange=async()=>{mutating=true;const done=check.checked;render();try{await api('/complete',{id:task.id,revision:task.revision,done,...(task.day?{day:task.day}:{})});notice(done?'Дело выполнено.':'Дело возвращено в работу.');}catch(e){notice(e.message);}finally{mutating=false;await load();}};}
if(!shown.length)root.append(el('p',!selected.length?'Пунктов пока нет. Администратор может добавить их в этот раздел.':filter==='done'?'Выполненных дел пока нет.':filter==='open'?'Все дела сделаны.':'Дел пока нет.'));}
async function load(){if(loading)return;loading=true;try{const d=await api();items=d.items;render();document.dispatchEvent(new CustomEvent('desk-sync',{detail:{ok:true}}));}catch(e){notice(e.message);document.dispatchEvent(new CustomEvent('desk-sync',{detail:{ok:false}}));}finally{loading=false;}}
$('#task-create').onsubmit=async e=>{e.preventDefault();const b=e.currentTarget.querySelector('button');if(b.disabled)return;b.disabled=true;const text=$('#task-text').value;try{await api('/create',{text,requestId,kind:$('#task-kind').value});requestId=crypto.randomUUID();kind=$('#task-kind').value;document.querySelectorAll('[data-kind]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.kind===kind)));$('#task-text').value='';notice('Дело добавлено.');await load();}catch(err){notice(err.message);}finally{b.disabled=false;}};
document.querySelectorAll('[data-kind]').forEach(b=>b.onclick=()=>{kind=b.dataset.kind;$('#task-kind').value=kind;document.querySelectorAll('[data-kind]').forEach(n=>n.setAttribute('aria-pressed',String(n===b)));render();});$('#task-kind').onchange=()=>{requestId=crypto.randomUUID();};$('#task-text').oninput=()=>{requestId=crypto.randomUUID();};
document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;document.querySelectorAll('[data-filter]').forEach(n=>n.setAttribute('aria-pressed',String(n===b)));render();});$('#tasks-refresh').onclick=load;
(async()=>{try{const r=await fetch('/api/admin/session',{cache:'no-store'});({user}=await r.json());if(!user){$('#tasks-login').hidden=false;notice('Войдите, чтобы увидеть дела команды.');return;}$('#tasks-workspace').hidden=false;$('#task-editor').hidden=user.role!=='admin';await load();setInterval(()=>{if(!document.hidden&&!mutating)load();},30000);document.addEventListener('visibilitychange',()=>{if(!document.hidden&&!mutating)load();});}catch{notice('Не удалось подключиться. Обновите страницу.');}})();})();
